# Standalone deterministic verifier: no imports, no I/O, exact integer arithmetic, fail-closed.

CLAIMED_R3 = [None,1,2,2,3,4,4,4,4,5]
WITNESSES = {
    1:[1], 2:[1,2], 3:[1,2], 4:[1,2,4], 5:[1,2,4,5],
    6:[1,2,4,5], 7:[1,2,4,5], 8:[1,2,4,5], 9:[1,2,4,8,9]
}

def is_3ap_free(s):
    ss = set(s)
    n = len(s)
    for i in range(n):
        for j in range(i+1, n):
            a, b = s[i], s[j]
            if (a + b) % 2 == 0:
                c = (a + b) // 2
                if c != a and c != b and c in ss:
                    return False
    return True

def r3_exact(N):
    best = 0
    for mask in range(1 << N):
        subset = [(i+1) for i in range(N) if (mask >> i) & 1]
        if is_3ap_free(subset) and len(subset) > best:
            best = len(subset)
    return best

def verify():
    for N in range(1, 10):
        val = r3_exact(N)
        if val != CLAIMED_R3[N]:
            raise AssertionError("r3(%d)=%d, claimed %d" % (N, val, CLAIMED_R3[N]))
        ws = sorted(WITNESSES[N])
        if len(ws) != CLAIMED_R3[N] or len(set(ws)) != len(ws):
            raise AssertionError("witness size mismatch at N=%d" % N)
        if any(x < 1 or x > N for x in ws):
            raise AssertionError("witness out of range at N=%d" % N)
        if not is_3ap_free(ws):
            raise AssertionError("witness not 3-AP-free at N=%d" % N)
    return True

RESULT = verify()
